import path from "node:path";
import { getMachineSecurityAnchorDir } from "../paths.js";
import { ProcessOwnershipJournal } from "./process-ownership-journal.js";

// Shared by every Broker in this JS runtime. A new Broker, different cwd or
// cleared audit history cannot turn a lost process owner into cleanup evidence.
// Linux additionally records ownership before the native launch. Retaining
// that record across restart is a fence, not proof of descendant cleanup.
const unresolvedOwners = new Map();
let journal = null;

function durableJournal() {
  if (process.platform !== "linux") return null;
  journal ??= new ProcessOwnershipJournal(
    path.join(getMachineSecurityAnchorDir(), "process-ownership-v1"),
  );
  return journal;
}

export function prepareProcessOwnership(executionId) {
  return durableJournal()?.prepare(executionId) ?? null;
}

export const PROCESS_OWNERSHIP_UNCONFIRMED =
  "BROKER_PROCESS_OWNERSHIP_UNCONFIRMED";

export function observeProcessOwnership(proc, executionId, lease = null) {
  // The facade emits close only after actual tree cleanup, or after a native
  // spawn that created no supervisor at all. Persist that fact before Bridge
  // callers receive close. An error/exit/PID probe cannot settle this record.
  if (lease)
    proc.prependOnceListener("close", () => {
      if (
        proc.pid &&
        proc.ownedProcessTreeEvidence?.cleanup?.confirmed !== true
      )
        return;
      try {
        lease.settle();
      } catch (error) {
        proc.emit("error", error);
      }
    });
  if (!proc?.ownedProcessTreeClosed || !proc.pid) return;
  const retain = (receipt) => {
    if (receipt?.cleanup?.confirmed !== false) return;
    lease?.retain();
    if (!unresolvedOwners.has(executionId)) {
      unresolvedOwners.set(executionId, { proc, durable: lease !== null });
    }
  };
  // Install before post-spawn bookkeeping and caller listeners. The error
  // precedes cleanup:unconfirmed, so reentrant callers must already be fenced.
  proc.on("error", (error) => {
    if (error.code === "EXTERNAL_AGENT_CLEANUP_UNCONFIRMED")
      retain(proc.ownedProcessTreeEvidence);
  });
  proc.once("cleanup:unconfirmed", retain);
}

export function getProcessOwnershipStatus() {
  const durable = durableJournal()?.inspect();
  return {
    blocked: unresolvedOwners.size > 0 || durable?.blocked === true,
    unresolvedExecutionIds: [
      ...new Set([
        ...unresolvedOwners.keys(),
        ...(durable?.blocked ? durable.pendingExecutionIds : []),
      ]),
    ],
    recoveryRequired: unresolvedOwners.size > 0 || durable?.blocked === true,
    durable:
      !!durable &&
      [...unresolvedOwners.values()].every((owner) => owner.durable),
    restartSafe: false,
  };
}

export function assertProcessOwnershipAvailable() {
  if (unresolvedOwners.size === 0) {
    durableJournal()?.assertAvailable();
    return;
  }
  const error = new Error(
    "Managed process execution is blocked because an earlier process tree has unconfirmed cleanup; restarting does not prove cleanup",
  );
  error.code = PROCESS_OWNERSHIP_UNCONFIRMED;
  error.recoveryRequired = true;
  error.executionStarted = false;
  throw error;
}

import { EventEmitter } from "node:events";
import { beforeEach, describe, expect, it, vi } from "vitest";

beforeEach(() => vi.resetModules());

function child(pid = 456) {
  return Object.assign(new EventEmitter(), {
    pid,
    ownedProcessTreeClosed: new Promise(() => {}),
  });
}

describe("Broker process ownership quarantine", () => {
  it("does not confuse spawn or ordinary signal errors with lost tree ownership", async () => {
    const ledger =
      await import("../../src/lib/process-execution-broker/process-ownership-quarantine.js");
    const proc = child();
    ledger.observeProcessOwnership(proc, "owned");
    proc.emit("error", new Error("signal failed"));
    proc.emit("cleanup:unconfirmed", { cleanup: { confirmed: true } });
    const noSpawn = child(undefined);
    noSpawn.pid = undefined;
    noSpawn.on("error", () => {});
    ledger.observeProcessOwnership(noSpawn, "not-started");
    noSpawn.emit("cleanup:unconfirmed", { cleanup: { confirmed: false } });
    expect(ledger.getProcessOwnershipStatus().blocked).toBe(false);
    expect(() => ledger.assertProcessOwnershipAvailable()).not.toThrow();
  });

  it("fences every process API before native launch, including new Brokers and reentry", async () => {
    const ledger =
      await import("../../src/lib/process-execution-broker/process-ownership-quarantine.js");
    const { default: broker } =
      await import("../../src/lib/process-execution-broker/index.js");
    const proc = child();
    const native = vi.fn(() => {
      throw new Error("native launch must not run");
    });
    broker._native = { spawn: native, spawnSync: native };
    ledger.observeProcessOwnership(proc, "owned");
    const launches = [
      () => broker.spawn("node", [], { policy: "allow" }),
      () => broker.spawnSync("node", [], { policy: "allow" }),
      () => broker.spawnPty({ spawn: native }, "node"),
      () => broker.exec("node", {}),
      () => broker.execSync("node"),
      () => broker.execFile("node", []),
      () => broker.execFileSync("node", []),
      () => broker.fork("fixture.cjs"),
      () => broker.beginWorkspaceTransaction({}),
      () => broker.recoverWorkspaceTransactions({}),
      () => broker.restoreWorkspaceTransaction("fixture"),
      () => broker.undoWorkspaceTransactionRestore("fixture"),
      () =>
        new broker.constructor().spawn("node", [], {
          cwd: "/different",
          policy: "allow",
        }),
    ];
    let reentryObserved = false;
    proc.on("error", () => {
      reentryObserved = true;
      for (const launch of launches)
        expect(launch).toThrow(
          expect.objectContaining({
            code: ledger.PROCESS_OWNERSHIP_UNCONFIRMED,
            recoveryRequired: true,
            executionStarted: false,
          }),
        );
    });
    proc.ownedProcessTreeEvidence = { cleanup: { confirmed: false } };
    proc.emit(
      "error",
      Object.assign(new Error("owner lost"), {
        code: "EXTERNAL_AGENT_CLEANUP_UNCONFIRMED",
      }),
    );
    proc.emit("cleanup:unconfirmed", proc.ownedProcessTreeEvidence);
    expect(reentryObserved).toBe(true);
    expect(native).not.toHaveBeenCalled();
    broker.flushAuditLog();
    const snapshot = broker.getProcessOwnershipStatus();
    expect(snapshot).toEqual({
      blocked: true,
      unresolvedExecutionIds: ["owned"],
      recoveryRequired: true,
      durable: false,
      restartSafe: false,
    });
    snapshot.unresolvedExecutionIds.length = 0;
    proc.emit("close", 0);
    expect(broker.getProcessOwnershipStatus().unresolvedExecutionIds).toEqual([
      "owned",
    ]);
    expect(launches[0]).toThrow();
  });
});

